<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\RefundService;

Auth::requirePermission('payments.manage');$tenantId=em_require_tenant();
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='refund'){
            Auth::requirePermission('refunds.manage');$paymentId=(int)($_POST['payment_id']??0);$reason=(string)($_POST['reason']??'');$r=(new RefundService())->requestFull($paymentId,$reason);em_flash($r['status']==='completed'?'ok':'error',$r['status']==='completed'?'Estorno integral concluído.':'Estorno solicitado ao provedor. Status: '.$r['status'].'.');
        }elseif($action==='reconcile-refund'){
            Auth::requirePermission('refunds.manage');$refundId=(int)($_POST['refund_id']??0);$r=(new RefundService())->reconcile($refundId);em_flash($r['status']==='completed'?'ok':'error',$r['status']==='completed'?'Estorno confirmado e concluído.':'O provedor ainda não confirmou o estorno.');
        }
    }catch(Throwable$e){em_flash('error',$e->getMessage());}
    em_go('payments');
}

$provider=trim((string)($_GET['provider']??''));$status=trim((string)($_GET['status']??''));
$sql='SELECT p.*,o.status order_status,o.payment_status order_payment_status,c.name customer_name,r.id refund_id,r.status refund_status,r.reason refund_reason FROM payments p JOIN orders o ON o.id=p.order_id LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN refunds r ON r.tenant_id=p.tenant_id AND r.payment_id=p.id WHERE p.tenant_id=?';$args=[$tenantId];if($provider!==''){$sql.=' AND p.provider=?';$args[]=$provider;}if($status!==''){$sql.=' AND p.status=?';$args[]=$status;}$sql.=' ORDER BY p.id DESC LIMIT 250';$s=$pdo->prepare($sql);$s->execute($args);$payments=$s->fetchAll();
$w=$pdo->prepare('SELECT * FROM webhook_events WHERE tenant_id=? ORDER BY id DESC LIMIT 100');$w->execute([$tenantId]);$webhooks=$w->fetchAll();
$stats=[];foreach([
 'paid'=>'SELECT COALESCE(SUM(amount_cents),0) FROM payments WHERE tenant_id=? AND status="paid"',
 'pending'=>'SELECT COUNT(*) FROM payments WHERE tenant_id=? AND status IN ("created","pending","authorized")',
 'failed'=>'SELECT COUNT(*) FROM payments WHERE tenant_id=? AND status="failed"',
 'refunded'=>'SELECT COALESCE(SUM(amount_cents),0) FROM payments WHERE tenant_id=? AND status="refunded"',
 'duplicates'=>'SELECT COUNT(*) FROM payments WHERE tenant_id=? AND status="duplicate_paid"',
 'duplicate_amount'=>'SELECT COALESCE(SUM(amount_cents),0) FROM payments WHERE tenant_id=? AND status="duplicate_paid"'
]as$k=>$q){$x=$pdo->prepare($q);$x->execute([$tenantId]);$stats[$k]=$x->fetchColumn();}

$providerTotals=[];$pt=$pdo->prepare('SELECT provider,COALESCE(SUM(amount_cents),0) amount FROM payments WHERE tenant_id=? AND status="paid" GROUP BY provider ORDER BY amount DESC');$pt->execute([$tenantId]);foreach($pt->fetchAll()as$row)$providerTotals[(string)$row['provider']]=(int)$row['amount'];$providerGrand=max(1,array_sum($providerTotals));
$daily=[];$dp=$pdo->prepare('SELECT created_at,amount_cents FROM payments WHERE tenant_id=? AND status="paid" ORDER BY id DESC LIMIT 500');$dp->execute([$tenantId]);foreach($dp->fetchAll()as$row){$key=date('d/m',strtotime((string)$row['created_at']));$daily[$key]=($daily[$key]??0)+(int)$row['amount_cents'];if(count($daily)>=8)break;}$daily=array_reverse($daily,true);$dailyMax=max(1,$daily?max($daily):1);

em_header('Financeiro / Pagamentos','payments');
?>
<section class="page-hero"><div><span class="eyebrow">FINANCEIRO</span><h2>Recebimentos e conciliação</h2><p>Acompanhe vendas, transações, estornos, conciliação e alertas de pagamento em uma única visão.</p></div><div class="hero-actions"><a class="button secondary" href="<?= Security::e(app_url('?route=cash')) ?>">Turno de caixa</a><a class="button secondary" href="<?= Security::e(app_url('?route=reports')) ?>">Relatórios</a></div></section>
<section class="grid finance-summary"><div class="card metric"><span class="muted">Faturamento confirmado</span><strong><?= em_money($stats['paid']) ?></strong></div><div class="card metric"><span class="muted">Estornado</span><strong><?= em_money($stats['refunded']) ?></strong></div><div class="card metric"><span class="muted">Pendentes</span><strong><?= (int)$stats['pending'] ?></strong></div><div class="card metric"><span class="muted">Falharam</span><strong><?= (int)$stats['failed'] ?></strong></div></section>
<?php if((int)$stats['duplicates']>0):?><div class="alert error" style="margin-top:14px"><strong>Atenção:</strong> <?= (int)$stats['duplicates'] ?> cobrança(s) duplicada(s), totalizando <?= em_money($stats['duplicate_amount']) ?>. O pedido permanece válido pelo pagamento vencedor; revise o estorno somente da cobrança marcada como duplicada.</div><?php endif;?>
<section class="finance-methods" style="margin-top:14px"><article class="card"><div class="section-head"><div><span class="eyebrow">EVOLUÇÃO</span><h2>Faturamento recente</h2></div></div><div class="chart-bars"><?php if(!$daily):?><div class="muted">Ainda não há pagamentos confirmados.</div><?php else:?><?php foreach($daily as$label=>$value):$height=max(7,(int)round($value*100/$dailyMax));?><div class="chart-bar" style="height:<?= $height ?>%" title="<?= Security::e($label.' · '.em_money($value)) ?>"><span><?= Security::e($label) ?></span></div><?php endforeach;?><?php endif;?></div></article><article class="card"><div class="section-head"><div><span class="eyebrow">MÉTODOS</span><h2>Por provedor</h2></div></div><div class="method-list"><?php foreach($providerTotals as$name=>$amount):$pct=(int)round($amount*100/$providerGrand);?><div class="method-row"><span><?= Security::e(ucfirst($name)) ?></span><div class="channel-track"><div class="channel-fill" style="width:<?= $pct ?>%"></div></div><strong><?= $pct ?>%</strong></div><?php endforeach;?><?php if(!$providerTotals):?><span class="muted">Sem pagamentos confirmados.</span><?php endif;?></div></article></section>

<section class="card" style="margin-top:14px"><div class="section-head"><div><span class="eyebrow">TRANSAÇÕES</span><h2>Movimentações recentes</h2></div></div><form method="get" class="actions" style="margin-bottom:12px"><input type="hidden" name="route" value="payments"><select name="provider"><option value="">Todos os provedores</option><?php foreach(['stripe','pagbank','mercadopago','manual']as$pv):?><option value="<?= $pv ?>"<?= em_selected($provider,$pv) ?>><?= Security::e(ucfirst($pv)) ?></option><?php endforeach;?></select><select name="status"><option value="">Todos os status</option><?php foreach(['created','pending','authorized','paid','duplicate_paid','failed','cancelled','refunded','partially_refunded']as$st):?><option value="<?= $st ?>"<?= em_selected($status,$st) ?>><?= Security::e($st) ?></option><?php endforeach;?></select><button class="secondary">Filtrar</button></form><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Pedido</th><th>Cliente</th><th>Método</th><th>Valor</th><th>Status</th><th>Transação</th><th>Ações</th></tr></thead><tbody><?php foreach($payments as$p):?><tr><td><?= Security::e($p['created_at']??'') ?></td><td><a href="<?= Security::e(app_url('?route=orders&view='.(int)$p['order_id'])) ?>"><strong>#<?= (int)$p['order_id'] ?></strong></a></td><td><?= Security::e($p['customer_name']??'—') ?></td><td><?= Security::e(ucfirst((string)$p['provider'])) ?></td><td><strong><?= em_money($p['amount_cents']) ?></strong></td><td><span class="badge"><?= Security::e($p['status']) ?></span><?php if($p['status']==='duplicate_paid'):?><br><small class="muted">Não reaplicar efeitos do pedido</small><?php endif;?></td><td><code><?= Security::e($p['provider_payment_id']??'—') ?></code></td><td><?php if($p['refund_id']):?><span class="badge"><?= Security::e($p['refund_status']) ?></span><br><small><?= Security::e($p['refund_reason']??'') ?></small><?php if(Auth::can('refunds.manage')&&$p['refund_status']==='provider_pending'):?><form method="post" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="reconcile-refund"><input type="hidden" name="refund_id" value="<?= (int)$p['refund_id'] ?>"><button class="secondary compact">Reverificar</button></form><?php elseif(Auth::can('refunds.manage')&&$p['refund_status']==='failed'):?><form method="post" style="margin-top:6px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="reason" value="<?= Security::e($p['refund_reason']??'Nova tentativa de estorno') ?>"><button class="secondary compact">Tentar novamente</button></form><?php endif;?><?php elseif(Auth::can('refunds.manage')&&in_array($p['status'],['paid','duplicate_paid'],true)):?><?php $duplicate=$p['status']==='duplicate_paid';?><form method="post" onsubmit="return confirm('<?= $duplicate?'Confirmar devolução da cobrança duplicada? O pedido original continuará pago e ativo.':'Confirmar estorno integral? Esta operação devolve o valor e cancela o pedido após confirmação do provedor.' ?>')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="refund"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input name="reason" maxlength="500" required minlength="5" placeholder="<?= $duplicate?'Cobrança duplicada':'Motivo do estorno' ?>" style="min-width:160px"><button class="secondary compact" style="margin-top:5px"><?= $duplicate?'Devolver duplicado':'Estornar' ?></button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if(Auth::can('audit.view')):?><details class="technical-details" style="margin-top:12px"><summary>Webhooks e validação técnica</summary><section class="card"><div class="section-head"><h2>Últimos webhooks</h2><span class="muted">Assinatura + idempotência</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Provedor</th><th>ID evento</th><th>Assinatura</th><th>Status</th><th>Processado</th></tr></thead><tbody><?php foreach($webhooks as$w):?><tr><td><?= Security::e($w['provider']) ?></td><td><code><?= Security::e($w['external_event_id']) ?></code></td><td><?= $w['signature_valid']?'Válida':'Inválida' ?></td><td><?= Security::e($w['status']) ?></td><td><?= Security::e($w['processed_at']??'—') ?></td></tr><?php endforeach;?></tbody></table></div></section></details><?php endif;?>
<?php em_footer();
